objects.ses:
on open {
  if flag(escrivaninha_aberta) { say "Já está aberta. Só papéis de contas lá dentro." }
  else { set escrivaninha_aberta; show "chave de latão"; play "tampa de madeira de escrivaninha rolando e abrindo"; say "A tampa corre com um ruído seco. Entre contas de luz, uma pequena chave de latão." }
}

on examine {
  say "O pêndulo vai e vem, tique, taque. Alguém continua dando corda nele. Os ponteiros marcam a hora certa, mas o calendário da parede parou há três semanas."
}

scene_54fc0d3c.ses:
on first_enter {
  say "Lúcia Albuquerque deixou a chave com você: 'Meu irmão sumiu há três semanas. A polícia desistiu. Eu não.'"
}

objects.ses:
on open {
  if flag(bau_aberto) { say "Já está aberto." }
  else { say "Trancado. A fechadura é pequena, de latão." }
}
on use with "chave de latão" {
  if flag(bau_aberto) { say "Já está aberto." }
  else {
    set bau_aberto; show "cartão perfurado"; show "carta das marés"; show lanterna
    play "fechadura de latão girando e tampa de baú de madeira rangendo"
    say "A chave gira. Dentro do baú: um cartão perfurado, uma carta náutica dobrada e uma lanterna."
  }
}

on examine {
  set leu_diario
  say "A última página, com letra apressada: 'A ilha só existe na maré morta. A máquina leva até lá, mas só com o cartão de coordenadas, que guardei no baú do sótão. A passagem para o laboratório fica atrás da estante do porão: é só empurrar a lateral esquerda.'"
}

on push {
  if flag(estante_movida) { say "A passagem já está aberta, a leste." }
  else if flag(leu_diario) {
    set estante_movida; link leste to "Passagem Secreta"; link oeste to "Porão" in "Passagem Secreta"
    play "estante pesada de madeira deslizando sobre piso de cimento"
    say "Você empurra a lateral esquerda. A estante gira sobre um eixo escondido e revela um corredor de pedra, a leste."
  }
  else { say "Ela não se mexe. As marcas no chão dizem que já se moveu muitas vezes; deve haver um jeito certo." }
}
on pull { say "Ela não sai do lugar puxando." }

on pull {
  if flag(energia) { say "Já está ligada." }
  else { set energia; play "alavanca de metal puxada e máquinas elétricas ganhando força, zumbido crescente"; say "Você puxa a alavanca. As luzes piscam, os mostradores sobem e o anel começa a zumbir." }
}
on push { say "Ela está para baixo; teria de puxar." }

on use with "cartão perfurado" {
  if flag(painel_programado) { say "O cartão já está no painel." }
  else { set painel_programado; remove "cartão perfurado"; play "cartão de papel entrando numa leitora mecânica, cliques e bipes"; say "O painel engole o cartão, estala por um tempo e mostra uma linha de números. Coordenadas gravadas." }
}

on use {
  if flag(portal_ativo) { say "O anel está aberto. É só entrar." }
  else if not flag(energia) { say "Nada acontece. A máquina está sem energia." }
  else if not flag(painel_programado) {
    play "descarga elétrica violenta e estrondo de energia"
    end "O anel se acende sem destino nenhum. A luz azul puxa você para dentro e espalha cada pedaço seu entre lugar nenhum e coisa nenhuma. Sem coordenadas, a máquina de Tomás não leva a lugar algum."
  }
  else {
    set portal_ativo; link entrar to "Colina da Chegada"
    play "zumbido elétrico crescendo até um redemoinho de energia se abrir"
    say "O anel acende por dentro: um redemoinho de luz azul, com cheiro de mar. Dá para entrar."
  }
}

scene_54ecade0.ses:
on first_enter {
  say "Você atravessa a luz e cai de joelhos numa trilha quente. O ar é salgado. Não há sinal de casa, nem de ninguém."
}

objects.ses:
on examine {
  say "Contas do Capitão Rocha, contrabandista. A última anotação: 'Guardei a bússola, o remo e a bomba no depósito. A chave ficou no tronco oco do pântano, onde nenhum ladrão mete a mão. Quem quiser a ilhota que espere a maré morta e leve a carta.'"
}

on open {
  if flag(deposito_aberto) { say "Já está aberta. O depósito fica ao norte." }
  else { say "O cadeado de ferro não cede." }
}
on use with "chave de ferro" {
  if flag(deposito_aberto) { say "Já está aberta." }
  else { set deposito_aberto; link norte to "Depósito dos Fundos"; link sul to "Posto do Capitão Rocha" in "Depósito dos Fundos"; play "cadeado de ferro enferrujado abrindo e porta de madeira rangendo"; say "O cadeado abre com um estalo. A porta dá para o depósito, ao norte." }
}

on open {
  if flag(bau_capitao_aberto) { say "Já está aberto." }
  else { set bau_capitao_aberto; show bússola; show remo; show "bomba de ar"; play "tampa pesada de baú com ferragens abrindo"; say "A tampa é pesada. Dentro: uma bússola de latão, um remo curto e uma bomba de ar de pé." }
}

on open {
  if flag(tronco_revirado) { say "Não há mais nada lá dentro." }
  else { set tronco_revirado; show "chave de ferro"; play "mão revirando folhas molhadas e madeira podre"; say "Você enfia a mão no oco, entre folhas podres, e toca em metal: uma chave de ferro." }
}
on use { say "Talvez dê para revirar o oco dele." }

on examine {
  if flag(bote_cheio) { say "Cheio e firme. Pesado, mas dá para arrastar." }
  else { say "Murcho, mas sem furos. Precisa de ar." }
}
on use with "bomba de ar" {
  if flag(bote_cheio) { say "Já está cheio." }
  else { set bote_cheio; play "bomba de ar de pé bombeando e bote de borracha enchendo"; say "Você bombeia até o braço doer. O bote endurece, inteiro." }
}
on push {
  if not flag(bote_cheio) { say "Murcho assim, não vai flutuar." }
  else { set bote_na_praia; hide self; show "bote vermelho"; play "bote de borracha sendo arrastado sobre areia"; say "Você arrasta o bote pela trilha, até a beira da água na praia, ao norte." }
}
on pull { say "Melhor empurrar: a trilha para a praia é ao norte." }

scene_13871910.ses:
on enter {
  if not has(lanterna) {
    play "escorregão em pedra molhada e queda no escuro, eco"
    end "Sem luz, você dá dois passos no escuro, pisa no musgo e escorrega para o buraco no meio da fenda. Ninguém nunca vai saber onde você caiu."
  } else {
    say "A luz da lanterna desenha a borda do buraco no meio do chão. Você contorna devagar."
  }
}

objects.ses:
on use with remo {
  if flag(bote_na_agua) { say "O bote já está na água. É só remar para o norte." }
  else {
    set bote_na_agua; link norte to "Mar Aberto"
    play "bote de borracha sendo empurrado para a água, remo batendo no mar"
    say "Você empurra o bote para a água e sobe nele com o remo. O mar aberto fica ao norte."
  }
}
on push { say "Na água, sem remo, ele só ia ficar boiando." }

scene_2421e7f8.ses:
on enter {
  if not has(bússola) {
    play "neblina densa, vento uivando e ondas grandes"
    end "Uma névoa branca cai de repente sobre o mar. Sem saber para onde fica o norte, você rema em círculos até as forças acabarem. O bote vermelho some na neblina."
  } else {
    say "Uma névoa começa a subir do mar, mas a agulha da bússola aponta firme para o norte."
  }
}

objects.ses:
on use with "carta das marés" {
  if flag(mare_baixa) { say "O caminho ao norte já está aberto." }
  else {
    set mare_baixa; remove "carta das marés"; link norte to "Templo da Maré"
    play "ronco grave de pedra e água recuando, ondas se afastando"
    say "Você deita a carta no sulco. As ondas entalhadas acendem uma a uma, e um ronco vem do chão. Ao norte, a mata se abre: uma trilha de pedras que antes estava debaixo d'água."
  }
}

on open { say "Não há maçaneta. Só o encaixe redondo no centro." }
on use with "medalhão de coral" {
  play "porta de pedra pesada se abrindo com estrondo grave"
  end "O medalhão encaixa com um clique. A porta afunda no chão e, lá dentro, à luz verde das algas, Tomás Albuquerque levanta a cabeça, magro e barbudo, mas vivo. 'A maré me prendeu aqui', ele sussurra. 'Achei que ninguém viria.' Você o ajuda a ficar de pé. Lá fora, a água já começa a subir; é hora de voltar para casa."
}
